(function (window) {
  function Vditor(target, options) {
    var container = typeof target === 'string' ? document.querySelector(target) : target;
    options = options || {};
    if (!container) return;
    container.innerHTML = '';
    container.classList.add('vditor-lite');
    var editor = document.createElement('div');
    editor.className = 'vditor-lite-editor';
    editor.contentEditable = 'true';
    editor.spellcheck = false;
    editor.textContent = options.value || '';
    var hint = document.createElement('div');
    hint.className = 'vditor-lite-hint';
    hint.textContent = '支持 Markdown 与 LaTeX，保存后会以文档形式渲染。';
    container.appendChild(editor);
    container.appendChild(hint);
    this.container = container;
    this.editor = editor;
    if (options.after) {
      setTimeout(options.after, 0);
    }
  }
  Vditor.prototype.getValue = function () {
    return this.editor ? this.editor.textContent : '';
  };
  Vditor.prototype.setValue = function (value) {
    if (this.editor) this.editor.textContent = value || '';
  };
  Vditor.prototype.focus = function () {
    if (this.editor) this.editor.focus();
  };
  Vditor.prototype.destroy = function () {
    if (this.container) this.container.innerHTML = '';
  };
  window.Vditor = window.Vditor || Vditor;
})(window);
